<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantTermsOfUse\Domain\ValueObject\Accessor\TenantTermsOfUseActivationDateAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantTermsOfUseActivationDateAccessor trait.
 *
 * Covers null default, string/VO assignment via withActivationDate,
 * getActivationDate/activationDate accessors, and isActivationDateChanged with/without original.
 */
class TenantTermsOfUseActivationDateAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withActivationDate creates a new instance with the ActivationDate set
     * from a string value, and getActivationDate returns the primitive string.
     */
    public function testWithActivationDateFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantTermsOfUseActivationDateAccessorUnitTest();

        // Act
        $result = $holder->withActivationDate((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->getActivationDate());
    }
    /**
     * Asserts that withactivationDate has access to the value object
     * from a string value, and getActivationDate returns the primitive string.
     */
    public function testWithActivationDateFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantTermsOfUseActivationDateAccessorUnitTest();

        // Act
        $result = $holder->withActivationDate((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->activationDate()->value());
    }
    public function testChangedActivationDate(): void
    {
        // Arrange
        $holder = new ImplWithTenantTermsOfUseActivationDateAccessorUnitTest();
        $original = $holder->withActivationDate((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $same = $holder->withActivationDate((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $modified = $holder->withActivationDate((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')));

        // Act
        $unchanged = $holder->isActivationDateChanged();
        $withSame = $original->isActivationDateChanged($same);
        $withDiferent = $original->isActivationDateChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantTermsOfUseActivationDateAccessorUnitTest
{
    use TenantTermsOfUseActivationDateAccessor;
}
